-- Demo data for ESTIMATES (the unified Estimator), DEMO tenants only (is_demo = true).
-- Run AFTER, in this order:
--   1. supabase/migrations/0131_estimator.sql and 0213_estimate_template_catalogue.sql
--   2. scripts/seed-fence-materials-demo.sql   (the fence products and security profiles; NOT repeated here)
-- Idempotent. GENERATED by scripts/gen-estimate-seeds.ts from the real engine; do not edit by
-- hand, change src/lib/estimator/starterTemplates.ts or the products script and regenerate.
--
-- What it does, per demo tenant:
--   1. turns the Estimates module on (tenants.features.estimator = true) and the Products module
--      (the fence materials script already turns that one on);
--   2. refuses to go on if the fence products are missing (they are the catalogue the template
--      prices from: it picks each line's product by its fence_kind, pipe class, mesh and coating tags);
--   3. adds the locked "Chain-link fence" template (or refreshes it);
--   4. adds 2 sample fence estimates with their lines, totals and layout model already
--      stored, so the page shows everything without pressing Calculate. Margin 18%, VAT 15%.
--      A sample that already has a quote is left alone; nothing else is deleted.
-- Everything is illustrative: placeholder costs, not a real price or any company's method.
-- Does NOT touch Fence projects (fence_projects) or Big Blue.

do $seed$
declare
  t uuid;
  tpl uuid;
  tpl_version int;
  acct uuid;
  cur text;
  est uuid;
  next_seq int;
  fresh boolean;
  fence_products int;
  v_params jsonb;
  v_totals jsonb;
  v_model jsonb;
  v_lines jsonb;
begin
  if not exists (select 1 from information_schema.columns where table_name = 'estimate_templates' and column_name = 'locked') then
    raise exception 'Run supabase/migrations/0213_estimate_template_catalogue.sql first (estimate_templates.locked is missing).';
  end if;
  if to_regclass('public.estimate_templates') is null then
    raise exception 'Run supabase/migrations/0131_estimator.sql first.';
  end if;

  for t in select id from tenants where is_demo = true loop
    update tenants set features = coalesce(features, '{}'::jsonb) || '{"estimator": true, "products": true}'::jsonb where id = t;

    select count(*) into fence_products from products where tenant_id = t and custom_data->>'fence_kind' is not null;
    if fence_products < 26 then
      raise exception 'The demo tenant has % fence products, expected at least 26. Run scripts/seed-fence-materials-demo.sql first.', fence_products;
    end if;

    if not exists (select 1 from estimate_templates where tenant_id = t and lower(name) = lower('Chain-link fence')) then
      insert into estimate_templates (tenant_id, name, description, trade, geometry, version, is_active, quote_granularity, inputs, rates, rules, keywords, icon, locked, customer_visible)
      values (
        t, 'Chain-link fence', 'Perimeter or straight-run chain-link fence: posts, fabric, gates and fittings, priced from your catalogue.', 'fencing', 'chainlink_fence', 1, true, 'line',
        $inputs$[{"key":"total_length_m","label":"Fence length","type":"number","default":500,"min":1,"max":5000,"unit":"m","help":"The whole length of fence, gates included.","section":"The fence"},{"key":"closed_perimeter","label":"Goes all the way round","type":"boolean","default":true,"help":"Yes for a closed boundary (four corners). No for a single straight run (two end posts).","section":"The fence"},{"key":"post_spacing_m","label":"What is being protected","type":"select","default":"general","options":[{"key":"general","label":"General yard and storage","value":3,"attrs":{"pipe_class":"Schedule 40"}},{"key":"vehicle","label":"Vehicle and equipment compound","value":2.5,"attrs":{"pipe_class":"SS20"}},{"key":"bonded","label":"Bonded or high-value storage","value":2,"attrs":{"pipe_class":"SS40"}}],"help":"Sets how far apart the posts are and which pipe class they use.","section":"The fence"},{"key":"fabric_height_m","label":"Fence height","type":"number","default":2,"min":1,"max":6,"unit":"m","section":"The fence"},{"key":"mesh","label":"Mesh","type":"select","default":"standard","options":[{"key":"standard","label":"Standard 50x50, 2.5 mm","value":1,"attrs":{"mesh_spec":"Chain-link 50x50 . 2.5mm"}},{"key":"high_security","label":"High security 25x25, 3.0 mm","value":2,"attrs":{"mesh_spec":"Chain-link 25x25 . 3.0mm (high security)"}},{"key":"mini_mesh","label":"Mini-mesh 16x16, 4.9 mm","value":3,"attrs":{"mesh_spec":"Chain-link 16x16 . 4.9mm (mini-mesh)"}}],"section":"The fence"},{"key":"coating","label":"Coating","type":"select","default":"pvc","options":[{"key":"pvc","label":"PVC coated","value":1,"attrs":{"coating":"PVC coated"}}],"section":"The fence"},{"key":"straining_spacing_m","label":"Distance between straining posts","type":"number","default":100,"min":10,"max":500,"unit":"m","section":"The fence"},{"key":"gates_single_n","label":"Single gates","type":"number","default":0,"min":0,"max":20,"unit":"gates","section":"Gates"},{"key":"gates_single_w","label":"Single gate width","type":"number","default":1.2,"min":0.6,"max":3,"unit":"m","section":"Gates"},{"key":"gates_double_n","label":"Double gates","type":"number","default":2,"min":0,"max":20,"unit":"gates","section":"Gates"},{"key":"gates_double_w","label":"Double gate width","type":"number","default":5,"min":2,"max":12,"unit":"m","section":"Gates"},{"key":"gates_sliding_n","label":"Sliding gates","type":"number","default":0,"min":0,"max":20,"unit":"gates","section":"Gates"},{"key":"gates_sliding_w","label":"Sliding gate width","type":"number","default":6,"min":2,"max":20,"unit":"m","section":"Gates"},{"key":"truss_rods","label":"Truss rods at corners and straining posts","type":"boolean","default":true,"section":"Fittings"},{"key":"tension_wire","label":"Tension wire (3 rows)","type":"boolean","default":true,"section":"Fittings"},{"key":"tie_wire","label":"Tie wire","type":"boolean","default":true,"section":"Fittings"},{"key":"barbed_wire","label":"Barbed wire on top (3 strands)","type":"boolean","default":false,"section":"Fittings"},{"key":"mesh_colour","label":"Mesh colour","type":"select","default":"green","options":[{"key":"galvanised","label":"Galvanised","value":1,"visual":"galvanised"},{"key":"green","label":"Green PVC","value":2,"visual":"pvc_green"},{"key":"black","label":"Black PVC","value":3,"visual":"pvc_black"},{"key":"blue","label":"Blue PVC","value":4,"visual":"pvc_blue"}],"paints":"mesh","section":"Appearance"},{"key":"post_colour","label":"Post colour","type":"select","default":"green","options":[{"key":"galvanised","label":"Galvanised","value":1,"visual":"galvanised"},{"key":"green","label":"Green PVC","value":2,"visual":"pvc_green"},{"key":"black","label":"Black PVC","value":3,"visual":"pvc_black"},{"key":"blue","label":"Blue PVC","value":4,"visual":"pvc_blue"}],"paints":"posts","section":"Appearance"}]$inputs$::jsonb,
        $rates$[]$rates$::jsonb,
        $rules$[{"code":"line_posts","group":"Posts","description":"Line posts","uom":"pcs","qty":"n_LP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"line_post"},"from":["post_spacing_m","coating"]}}},{"code":"straining_posts","group":"Posts","description":"Straining posts","uom":"pcs","qty":"n_SP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"straining_post"},"from":["post_spacing_m","coating"]}}},{"code":"corner_posts","group":"Posts","description":"Corner posts","uom":"pcs","qty":"n_CP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"corner_post"},"from":["post_spacing_m","coating"]}}},{"code":"terminal_posts","group":"Posts","description":"Terminal posts","uom":"pcs","qty":"n_TP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"terminal_post"},"from":["post_spacing_m","coating"]}}},{"code":"gate_posts","group":"Posts","description":"Gate posts","uom":"pcs","qty":"n_GP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"gate_post"},"from":["post_spacing_m","coating"]}}},{"code":"fabric","group":"Chain-link fabric","description":"Chain-link fabric","uom":"m2","qty":"area_FB","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"fabric"},"from":["mesh","coating"]}}},{"code":"tension_bands","group":"Fittings and hardware","description":"Tension bands","uom":"pcs","qty":"(n_CP + n_TP + n_SP + n_GP) * max(3, ceil(fabric_height_m / 0.3))","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"tension_band"},"from":["coating"]}}},{"code":"brace_bands","group":"Fittings and hardware","description":"Brace bands","uom":"pcs","qty":"(n_CP + n_TP + n_SP + n_GP) * 2","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"brace_band"},"from":["coating"]}}},{"code":"rail_ends","group":"Fittings and hardware","description":"Rail ends","uom":"pcs","qty":"(n_CP + n_TP + n_SP + n_GP) * 2","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"rail_end"},"from":["coating"]}}},{"code":"carriage_bolts","group":"Fittings and hardware","description":"Carriage bolt sets","uom":"sets","qty":"qty_tension_bands + qty_brace_bands","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"carriage_bolt_set"},"from":["coating"]}}},{"code":"truss_sets","group":"Fittings and hardware","description":"Truss rod sets","uom":"sets","qty":"truss_rods * (n_CP + n_SP)","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"truss_rod_set"},"from":["coating"]}}},{"code":"tension_wire_m","group":"Wire","description":"Tension wire","uom":"m","qty":"tension_wire * round(total_length_m * 3)","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"tension_wire"},"from":["coating"]}}},{"code":"tie_wire_kg","group":"Wire","description":"Tie wire","uom":"kg","qty":"tie_wire * round(total_length_m * 0.0186, 1)","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"tie_wire"},"from":["coating"]}}},{"code":"barbed_wire_m","group":"Wire","description":"Barbed wire","uom":"m","qty":"barbed_wire * total_length_m * 3","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"barbed_wire"},"from":["coating"]}}}]$rules$::jsonb,
        array['fence', 'fencing', 'chain link', 'chainlink', 'perimeter', 'boundary', 'compound', 'yard', 'gate', 'posts', 'mesh', 'security fence', 'barbed wire']::text[], 'fence', true, false
      );
    else
      -- Already there: the catalogue fields are filled only where empty. A LOCKED starter is
      -- product-owned, so its inputs, rates and rules are refreshed to the current ones (the
      -- version goes up when they changed); an editable template of the workspace is left alone.
      update estimate_templates set
        keywords = coalesce(keywords, array['fence', 'fencing', 'chain link', 'chainlink', 'perimeter', 'boundary', 'compound', 'yard', 'gate', 'posts', 'mesh', 'security fence', 'barbed wire']::text[]),
        icon = coalesce(icon, 'fence')
      where tenant_id = t and lower(name) = lower('Chain-link fence');
      update estimate_templates set
        inputs = $inputs$[{"key":"total_length_m","label":"Fence length","type":"number","default":500,"min":1,"max":5000,"unit":"m","help":"The whole length of fence, gates included.","section":"The fence"},{"key":"closed_perimeter","label":"Goes all the way round","type":"boolean","default":true,"help":"Yes for a closed boundary (four corners). No for a single straight run (two end posts).","section":"The fence"},{"key":"post_spacing_m","label":"What is being protected","type":"select","default":"general","options":[{"key":"general","label":"General yard and storage","value":3,"attrs":{"pipe_class":"Schedule 40"}},{"key":"vehicle","label":"Vehicle and equipment compound","value":2.5,"attrs":{"pipe_class":"SS20"}},{"key":"bonded","label":"Bonded or high-value storage","value":2,"attrs":{"pipe_class":"SS40"}}],"help":"Sets how far apart the posts are and which pipe class they use.","section":"The fence"},{"key":"fabric_height_m","label":"Fence height","type":"number","default":2,"min":1,"max":6,"unit":"m","section":"The fence"},{"key":"mesh","label":"Mesh","type":"select","default":"standard","options":[{"key":"standard","label":"Standard 50x50, 2.5 mm","value":1,"attrs":{"mesh_spec":"Chain-link 50x50 . 2.5mm"}},{"key":"high_security","label":"High security 25x25, 3.0 mm","value":2,"attrs":{"mesh_spec":"Chain-link 25x25 . 3.0mm (high security)"}},{"key":"mini_mesh","label":"Mini-mesh 16x16, 4.9 mm","value":3,"attrs":{"mesh_spec":"Chain-link 16x16 . 4.9mm (mini-mesh)"}}],"section":"The fence"},{"key":"coating","label":"Coating","type":"select","default":"pvc","options":[{"key":"pvc","label":"PVC coated","value":1,"attrs":{"coating":"PVC coated"}}],"section":"The fence"},{"key":"straining_spacing_m","label":"Distance between straining posts","type":"number","default":100,"min":10,"max":500,"unit":"m","section":"The fence"},{"key":"gates_single_n","label":"Single gates","type":"number","default":0,"min":0,"max":20,"unit":"gates","section":"Gates"},{"key":"gates_single_w","label":"Single gate width","type":"number","default":1.2,"min":0.6,"max":3,"unit":"m","section":"Gates"},{"key":"gates_double_n","label":"Double gates","type":"number","default":2,"min":0,"max":20,"unit":"gates","section":"Gates"},{"key":"gates_double_w","label":"Double gate width","type":"number","default":5,"min":2,"max":12,"unit":"m","section":"Gates"},{"key":"gates_sliding_n","label":"Sliding gates","type":"number","default":0,"min":0,"max":20,"unit":"gates","section":"Gates"},{"key":"gates_sliding_w","label":"Sliding gate width","type":"number","default":6,"min":2,"max":20,"unit":"m","section":"Gates"},{"key":"truss_rods","label":"Truss rods at corners and straining posts","type":"boolean","default":true,"section":"Fittings"},{"key":"tension_wire","label":"Tension wire (3 rows)","type":"boolean","default":true,"section":"Fittings"},{"key":"tie_wire","label":"Tie wire","type":"boolean","default":true,"section":"Fittings"},{"key":"barbed_wire","label":"Barbed wire on top (3 strands)","type":"boolean","default":false,"section":"Fittings"},{"key":"mesh_colour","label":"Mesh colour","type":"select","default":"green","options":[{"key":"galvanised","label":"Galvanised","value":1,"visual":"galvanised"},{"key":"green","label":"Green PVC","value":2,"visual":"pvc_green"},{"key":"black","label":"Black PVC","value":3,"visual":"pvc_black"},{"key":"blue","label":"Blue PVC","value":4,"visual":"pvc_blue"}],"paints":"mesh","section":"Appearance"},{"key":"post_colour","label":"Post colour","type":"select","default":"green","options":[{"key":"galvanised","label":"Galvanised","value":1,"visual":"galvanised"},{"key":"green","label":"Green PVC","value":2,"visual":"pvc_green"},{"key":"black","label":"Black PVC","value":3,"visual":"pvc_black"},{"key":"blue","label":"Blue PVC","value":4,"visual":"pvc_blue"}],"paints":"posts","section":"Appearance"}]$inputs$::jsonb,
        rates = $rates$[]$rates$::jsonb,
        rules = $rules$[{"code":"line_posts","group":"Posts","description":"Line posts","uom":"pcs","qty":"n_LP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"line_post"},"from":["post_spacing_m","coating"]}}},{"code":"straining_posts","group":"Posts","description":"Straining posts","uom":"pcs","qty":"n_SP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"straining_post"},"from":["post_spacing_m","coating"]}}},{"code":"corner_posts","group":"Posts","description":"Corner posts","uom":"pcs","qty":"n_CP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"corner_post"},"from":["post_spacing_m","coating"]}}},{"code":"terminal_posts","group":"Posts","description":"Terminal posts","uom":"pcs","qty":"n_TP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"terminal_post"},"from":["post_spacing_m","coating"]}}},{"code":"gate_posts","group":"Posts","description":"Gate posts","uom":"pcs","qty":"n_GP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"gate_post"},"from":["post_spacing_m","coating"]}}},{"code":"fabric","group":"Chain-link fabric","description":"Chain-link fabric","uom":"m2","qty":"area_FB","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"fabric"},"from":["mesh","coating"]}}},{"code":"tension_bands","group":"Fittings and hardware","description":"Tension bands","uom":"pcs","qty":"(n_CP + n_TP + n_SP + n_GP) * max(3, ceil(fabric_height_m / 0.3))","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"tension_band"},"from":["coating"]}}},{"code":"brace_bands","group":"Fittings and hardware","description":"Brace bands","uom":"pcs","qty":"(n_CP + n_TP + n_SP + n_GP) * 2","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"brace_band"},"from":["coating"]}}},{"code":"rail_ends","group":"Fittings and hardware","description":"Rail ends","uom":"pcs","qty":"(n_CP + n_TP + n_SP + n_GP) * 2","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"rail_end"},"from":["coating"]}}},{"code":"carriage_bolts","group":"Fittings and hardware","description":"Carriage bolt sets","uom":"sets","qty":"qty_tension_bands + qty_brace_bands","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"carriage_bolt_set"},"from":["coating"]}}},{"code":"truss_sets","group":"Fittings and hardware","description":"Truss rod sets","uom":"sets","qty":"truss_rods * (n_CP + n_SP)","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"truss_rod_set"},"from":["coating"]}}},{"code":"tension_wire_m","group":"Wire","description":"Tension wire","uom":"m","qty":"tension_wire * round(total_length_m * 3)","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"tension_wire"},"from":["coating"]}}},{"code":"tie_wire_kg","group":"Wire","description":"Tie wire","uom":"kg","qty":"tie_wire * round(total_length_m * 0.0186, 1)","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"tie_wire"},"from":["coating"]}}},{"code":"barbed_wire_m","group":"Wire","description":"Barbed wire","uom":"m","qty":"barbed_wire * total_length_m * 3","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"barbed_wire"},"from":["coating"]}}}]$rules$::jsonb,
        locked = true,
        version = case when inputs is distinct from $inputs$[{"key":"total_length_m","label":"Fence length","type":"number","default":500,"min":1,"max":5000,"unit":"m","help":"The whole length of fence, gates included.","section":"The fence"},{"key":"closed_perimeter","label":"Goes all the way round","type":"boolean","default":true,"help":"Yes for a closed boundary (four corners). No for a single straight run (two end posts).","section":"The fence"},{"key":"post_spacing_m","label":"What is being protected","type":"select","default":"general","options":[{"key":"general","label":"General yard and storage","value":3,"attrs":{"pipe_class":"Schedule 40"}},{"key":"vehicle","label":"Vehicle and equipment compound","value":2.5,"attrs":{"pipe_class":"SS20"}},{"key":"bonded","label":"Bonded or high-value storage","value":2,"attrs":{"pipe_class":"SS40"}}],"help":"Sets how far apart the posts are and which pipe class they use.","section":"The fence"},{"key":"fabric_height_m","label":"Fence height","type":"number","default":2,"min":1,"max":6,"unit":"m","section":"The fence"},{"key":"mesh","label":"Mesh","type":"select","default":"standard","options":[{"key":"standard","label":"Standard 50x50, 2.5 mm","value":1,"attrs":{"mesh_spec":"Chain-link 50x50 . 2.5mm"}},{"key":"high_security","label":"High security 25x25, 3.0 mm","value":2,"attrs":{"mesh_spec":"Chain-link 25x25 . 3.0mm (high security)"}},{"key":"mini_mesh","label":"Mini-mesh 16x16, 4.9 mm","value":3,"attrs":{"mesh_spec":"Chain-link 16x16 . 4.9mm (mini-mesh)"}}],"section":"The fence"},{"key":"coating","label":"Coating","type":"select","default":"pvc","options":[{"key":"pvc","label":"PVC coated","value":1,"attrs":{"coating":"PVC coated"}}],"section":"The fence"},{"key":"straining_spacing_m","label":"Distance between straining posts","type":"number","default":100,"min":10,"max":500,"unit":"m","section":"The fence"},{"key":"gates_single_n","label":"Single gates","type":"number","default":0,"min":0,"max":20,"unit":"gates","section":"Gates"},{"key":"gates_single_w","label":"Single gate width","type":"number","default":1.2,"min":0.6,"max":3,"unit":"m","section":"Gates"},{"key":"gates_double_n","label":"Double gates","type":"number","default":2,"min":0,"max":20,"unit":"gates","section":"Gates"},{"key":"gates_double_w","label":"Double gate width","type":"number","default":5,"min":2,"max":12,"unit":"m","section":"Gates"},{"key":"gates_sliding_n","label":"Sliding gates","type":"number","default":0,"min":0,"max":20,"unit":"gates","section":"Gates"},{"key":"gates_sliding_w","label":"Sliding gate width","type":"number","default":6,"min":2,"max":20,"unit":"m","section":"Gates"},{"key":"truss_rods","label":"Truss rods at corners and straining posts","type":"boolean","default":true,"section":"Fittings"},{"key":"tension_wire","label":"Tension wire (3 rows)","type":"boolean","default":true,"section":"Fittings"},{"key":"tie_wire","label":"Tie wire","type":"boolean","default":true,"section":"Fittings"},{"key":"barbed_wire","label":"Barbed wire on top (3 strands)","type":"boolean","default":false,"section":"Fittings"},{"key":"mesh_colour","label":"Mesh colour","type":"select","default":"green","options":[{"key":"galvanised","label":"Galvanised","value":1,"visual":"galvanised"},{"key":"green","label":"Green PVC","value":2,"visual":"pvc_green"},{"key":"black","label":"Black PVC","value":3,"visual":"pvc_black"},{"key":"blue","label":"Blue PVC","value":4,"visual":"pvc_blue"}],"paints":"mesh","section":"Appearance"},{"key":"post_colour","label":"Post colour","type":"select","default":"green","options":[{"key":"galvanised","label":"Galvanised","value":1,"visual":"galvanised"},{"key":"green","label":"Green PVC","value":2,"visual":"pvc_green"},{"key":"black","label":"Black PVC","value":3,"visual":"pvc_black"},{"key":"blue","label":"Blue PVC","value":4,"visual":"pvc_blue"}],"paints":"posts","section":"Appearance"}]$inputs$::jsonb or rules is distinct from $rules$[{"code":"line_posts","group":"Posts","description":"Line posts","uom":"pcs","qty":"n_LP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"line_post"},"from":["post_spacing_m","coating"]}}},{"code":"straining_posts","group":"Posts","description":"Straining posts","uom":"pcs","qty":"n_SP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"straining_post"},"from":["post_spacing_m","coating"]}}},{"code":"corner_posts","group":"Posts","description":"Corner posts","uom":"pcs","qty":"n_CP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"corner_post"},"from":["post_spacing_m","coating"]}}},{"code":"terminal_posts","group":"Posts","description":"Terminal posts","uom":"pcs","qty":"n_TP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"terminal_post"},"from":["post_spacing_m","coating"]}}},{"code":"gate_posts","group":"Posts","description":"Gate posts","uom":"pcs","qty":"n_GP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"gate_post"},"from":["post_spacing_m","coating"]}}},{"code":"fabric","group":"Chain-link fabric","description":"Chain-link fabric","uom":"m2","qty":"area_FB","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"fabric"},"from":["mesh","coating"]}}},{"code":"tension_bands","group":"Fittings and hardware","description":"Tension bands","uom":"pcs","qty":"(n_CP + n_TP + n_SP + n_GP) * max(3, ceil(fabric_height_m / 0.3))","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"tension_band"},"from":["coating"]}}},{"code":"brace_bands","group":"Fittings and hardware","description":"Brace bands","uom":"pcs","qty":"(n_CP + n_TP + n_SP + n_GP) * 2","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"brace_band"},"from":["coating"]}}},{"code":"rail_ends","group":"Fittings and hardware","description":"Rail ends","uom":"pcs","qty":"(n_CP + n_TP + n_SP + n_GP) * 2","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"rail_end"},"from":["coating"]}}},{"code":"carriage_bolts","group":"Fittings and hardware","description":"Carriage bolt sets","uom":"sets","qty":"qty_tension_bands + qty_brace_bands","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"carriage_bolt_set"},"from":["coating"]}}},{"code":"truss_sets","group":"Fittings and hardware","description":"Truss rod sets","uom":"sets","qty":"truss_rods * (n_CP + n_SP)","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"truss_rod_set"},"from":["coating"]}}},{"code":"tension_wire_m","group":"Wire","description":"Tension wire","uom":"m","qty":"tension_wire * round(total_length_m * 3)","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"tension_wire"},"from":["coating"]}}},{"code":"tie_wire_kg","group":"Wire","description":"Tie wire","uom":"kg","qty":"tie_wire * round(total_length_m * 0.0186, 1)","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"tie_wire"},"from":["coating"]}}},{"code":"barbed_wire_m","group":"Wire","description":"Barbed wire","uom":"m","qty":"barbed_wire * total_length_m * 3","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"barbed_wire"},"from":["coating"]}}}]$rules$::jsonb then version + 1 else version end
      where tenant_id = t and lower(name) = lower('Chain-link fence') and locked = true;
    end if;
    -- The layer map needs migration 0215 (estimate_templates.drawing_map); without it the starter is simply left without one.
    if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'estimate_templates' and column_name = 'drawing_map') then
      update estimate_templates set drawing_map = $drawing_map$[{"input":"total_length_m","measure":"length_m","layers":["FENCE"]}]$drawing_map$::jsonb
      where tenant_id = t and lower(name) = lower('Chain-link fence') and locked = true and drawing_map is distinct from $drawing_map$[{"input":"total_length_m","measure":"length_m","layers":["FENCE"]}]$drawing_map$::jsonb;
